CREATE POLICY "perm_contas_a_pagar_select" ON public.contas_a_pagar FOR SELECT TO authenticated USING (empresa_id = public.get_my_empresa_id() AND (public.is_admin_user(auth.uid()) OR public.has_permissao('financeiro', 'ver')));
CREATE POLICY "perm_contas_a_pagar_insert" ON public.contas_a_pagar FOR INSERT TO authenticated WITH CHECK (empresa_id = public.get_my_empresa_id() AND (public.is_admin_user(auth.uid()) OR public.has_permissao('financeiro', 'criar')));
CREATE POLICY "perm_contas_a_pagar_update" ON public.contas_a_pagar FOR UPDATE TO authenticated USING (empresa_id = public.get_my_empresa_id() AND (public.is_admin_user(auth.uid()) OR public.has_permissao('financeiro', 'editar')));
CREATE POLICY "perm_contas_a_pagar_delete" ON public.contas_a_pagar FOR DELETE TO authenticated USING (empresa_id = public.get_my_empresa_id() AND (public.is_admin_user(auth.uid()) OR public.has_permissao('financeiro', 'excluir')));
CREATE POLICY "perm_movimentacoes_financeiras_select" ON public.movimentacoes_financeiras FOR SELECT TO authenticated USING (empresa_id = public.get_my_empresa_id() AND (public.is_admin_user(auth.uid()) OR public.has_permissao('financeiro', 'ver')));
CREATE POLICY "perm_movimentacoes_financeiras_insert" ON public.movimentacoes_financeiras FOR INSERT TO authenticated WITH CHECK (empresa_id = public.get_my_empresa_id() AND (public.is_admin_user(auth.uid()) OR public.has_permissao('financeiro', 'criar') OR public.has_permissao('compras', 'criar') OR public.has_permissao('pecas', 'criar')));
CREATE POLICY "perm_movimentacoes_financeiras_update" ON public.movimentacoes_financeiras FOR UPDATE TO authenticated USING (empresa_id = public.get_my_empresa_id() AND (public.is_admin_user(auth.uid()) OR public.has_permissao('financeiro', 'editar')));
CREATE POLICY "perm_movimentacoes_financeiras_delete" ON public.movimentacoes_financeiras FOR DELETE TO authenticated USING (empresa_id = public.get_my_empresa_id() AND (public.is_admin_user(auth.uid()) OR public.has_permissao('financeiro', 'excluir')));